const source = [$json.textPlain, $json.textHtml, $json.snippet].map(value => String(value ?? '')).find(value => value.trim()) ?? '';
const raw = source.replace(/<br\s*\/?>(?=.)/gi, '\n').replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&euro;|&#x20ac;|&#8364;/gi, '€');
const lines = raw.split(/\r?\n/).map(line => line.replace(/\s+/g, ' ').trim()).filter(Boolean);
const boughtAt = lines.findIndex(line => /^Comprado por:?$/i.test(line));
if (boughtAt < 0 || !lines[boughtAt + 1] || !lines[boughtAt + 2]) throw new Error('No se encontro el bloque Comprado por en el correo de Wallapop.');
const comprador_nombre = lines[boughtAt + 1];
const productLine = lines[boughtAt + 2];
const priceMatch = productLine.match(/\s((?:\d{1,3}(?:\.\d{3})*|\d+)(?:[.,]\d{1,2})?)\s*€\s*$/);
if (!priceMatch) throw new Error('No se encontro el importe en la linea del producto de Wallapop.');
const rawPrice = priceMatch[1];
const importe_total = Number(rawPrice.includes(',') ? rawPrice.replace(/\./g, '').replace(',', '.') : rawPrice);
const titulo_wallapop = productLine.slice(0, priceMatch.index).trim();
const dateLine = lines.find(line => /^Fecha de compra:/i.test(line));
const dateMatch = dateLine?.match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
if (!dateMatch) throw new Error('No se encontro la fecha de compra en el correo de Wallapop.');
const year = dateMatch[3].length === 2 ? `20${dateMatch[3]}` : dateMatch[3];
const fecha = `${year}-${dateMatch[2].padStart(2, '0')}-${dateMatch[1].padStart(2, '0')}`;
const origen_id = String($json.id ?? $json.messageId ?? $json.message_id ?? $json.threadId ?? '').trim();
if (!origen_id) throw new Error('El disparador de Gmail no devolvio un id estable del mensaje.');
return [{ json: { proyecto_id: Number($env.ERP_PROJECT_ID || 1), origen_id, fecha, comprador_nombre, titulo_wallapop, importe_total, unidades: 1, estado: 'pendiente' } }];
